begin;
create extension if not exists pgtap with schema extensions;
select plan(24);
insert into public.colleges(code,name) values('CERT-TEST','Certificate Test College');
insert into public.programs(college_id,name) select id,'Certificate Test Program' from public.colleges where code='CERT-TEST';
insert into public.event_categories(name,slug) values('Certificate Test','certificate-test');
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,is_anonymous,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','att-'||n||'@test.local',now(),'{}','{"first_name":"Attendance","last_name":"Test"}',false,now(),now() from generate_series(1,8)n;
update public.profiles set student_id='ATT-'||right(id::text,4),college_id=(select id from public.colleges where code='CERT-TEST'),program_id=(select id from public.programs where name='Certificate Test Program'),year_level=1,avatar_path=id::text||'/photo.png',privacy_consented_at=now(),privacy_notice_version='2026-10-draft' where id::text like 'e1000000-%' ;
update public.profiles set organizer_status='active',organizer_since=now() where id='e1000000-0000-4000-8000-000000000001';
insert into public.events(id,organizer_id,title,description,venue,category_id,starts_at,ends_at,registration_opens_at,registration_closes_at,status,attendance_policy,allow_onsite_registration)
values('ee000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','Certificate Test Event',repeat('description ',3),'University Hall',(select id from public.event_categories where slug='certificate-test'),now()-interval '1 hour',now()+interval '1 hour',now()-interval '1 day',now()-interval '2 hours','published','time_in_and_out',true);
insert into public.event_registrations(id,event_id,user_id,status) select ('ea000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ee000000-0000-4000-8000-000000000001',('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=8 then 'pending'::public.registration_status else 'approved'::public.registration_status end from generate_series(2,8)n;
update public.events set certificates_enabled=true where id='ee000000-0000-4000-8000-000000000001';
insert into public.attendance_records(registration_id,event_id,user_id,time_in_method,time_in_at,time_out_at,time_out_method,flag,status,revoked_at,revoked_by)
select ('ea000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ee000000-0000-4000-8000-000000000001',('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'qr',now()-interval '30 minutes',case when n=3 then null else now() end,case when n=3 then null else 'qr' end,case when n=4 then 'shared_device' end,case when n=6 then 'revoked' else 'present' end,case when n=6 then now() end,case when n=6 then 'e1000000-0000-4000-8000-000000000001'::uuid end from generate_series(2,6)n;
update public.profiles set identity_flagged_at=now(),identity_flag_reason='Test identity review' where id='e1000000-0000-4000-8000-000000000005';
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
set local role authenticated;
select is(public.issue_certificates('ee000000-0000-4000-8000-000000000001')->>'code','invalid_status','cannot issue before completion');
select is(public.complete_event('ee000000-0000-4000-8000-000000000001'),'ok','event completed');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'eligible')::int,1,'one eligible');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'missing_time_out')::int,1,'missing timeout blocked');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'blocked_by_flags')::int,1,'unresolved flag blocked');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'identity_review')::int,1,'identity flag blocked');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'revoked_attendance')::int,1,'revoked attendance blocked');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'absent')::int,1,'absent blocked');
select is((public.get_certificate_eligibility('ee000000-0000-4000-8000-000000000001')->'counts'->>'not_approved')::int,1,'pending blocked');
select is((public.issue_certificates('ee000000-0000-4000-8000-000000000001')->>'issued')::int,1,'eligible certificate issued');
select is((public.issue_certificates('ee000000-0000-4000-8000-000000000001')->>'issued')::int,0,'duplicate issuance prevented');
select is(public.set_certificate_enabled('ee000000-0000-4000-8000-000000000001',false),'certificates_locked','settings lock after issuance');
select is(public.correct_attendance('ea000000-0000-4000-8000-000000000002','revoke','Test reason'),'invalid_status','attendance cannot change under valid certificate');
select set_config('test.cert',(select id::text from public.certificates where event_id='ee000000-0000-4000-8000-000000000001'),true);
select set_config('test.verify',(select verification_code from public.certificates where id=current_setting('test.cert')::uuid),true);
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":false}',true);
select is((select count(*)::int from public.certificates),1,'holder reads own certificate');
select throws_ok($$update public.profiles set student_id='CHANGED' where id=auth.uid()$$,'23514',null,'student ID locked after issuance');
select lives_ok($$update public.profiles set first_name='Corrected' where id=auth.uid()$$,'name may change');
select is((select recipient_name from public.certificates where id=current_setting('test.cert')::uuid),'Attendance Test','snapshot not changed by profile edit');
select is(public.issue_certificates('ee000000-0000-4000-8000-000000000001')->>'code','not_permitted','participant cannot issue');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","is_anonymous":false}',true);
select is((select count(*)::int from public.certificates),0,'other holder certificate hidden');
set local role anon;
select is(public.verify_certificate(current_setting('test.verify'))->>'status','Valid','anonymous verification valid');
select ok(not (public.verify_certificate(current_setting('test.verify'))?|array['user_id','student_id','email','registration_id','revoke_reason']),'verification whitelist private');
select ok(public.verify_certificate('bad-code') is null,'unknown verification neutral');
reset role;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
set local role authenticated;
select is(public.revoke_certificate(current_setting('test.cert')::uuid,'Verified identity issue'),'ok','owner revokes certificate');
select is(public.verify_certificate(current_setting('test.verify'))->>'status','Revoked','public verification reflects revocation');
select * from finish();
rollback;
